#ifndef INSTRUCTION_HPP
#define INSTRUCTION_HPP

#include <utility>
#include "Common.h"
#include <string>
#include <iostream>

typedef unsigned int Instruction;

struct InvalidAccess {
    std::string message;
    InvalidAccess(const std::string &msg) : message(msg) {}
};

struct InstructionBase {
    unsigned opcode:6, rs1:5, rs2:5, rd:5, funct3:3, funct7:7, imm:20, inst:32;
    char t;

    InstructionBase() : opcode(0), rs1(0), rs2(0), rd(0), funct3(0), funct7(0), imm(0), inst(0), t(' ') {}
    InstructionBase(unsigned i) : opcode(i >> 26 & 0x3F), rs1(0), rs2(0), rd(i >> 7 & 0x1F), funct3(i >> 12 & 0x7), funct7(0), imm(i & 0xFFF), inst(i), t('I') {}

    static InstructionBase nop() {
        return InstructionBase();
    }

    static unsigned bin_mask(int digits) {
        return (1 << digits) - 1;
    }

    static unsigned get_digits(unsigned int n, int hi, int lo) {
        return (n >> lo) & bin_mask(hi - lo + 1);
    }

    static unsigned expand_digit(unsigned int digit, int lo) {
        if ((digit >> (lo - 1)) & 1)
            return digit | ~bin_mask(lo);
        else
            return digit;
    }

    bool is_nop() const {
        return inst == 0;
    }

    bool is_valid(const std::string &key) const {
        if (key == "opcode") return true;
        if (key == "rs1" && (t == 'R' || t == 'I')) return true;
        if (key == "rs2" && (t == 'R' || t == 'S')) return true;
        if (key == "rd" && (t == 'R' || t == 'I' || t == 'U' || t == 'J')) return true;
        if (key == "funct3") return true;
        if (key == "funct7" && t == 'R') return true;
        if (key == "imm") return true;
        return false;
    }

    void verify(const std::string &key) const {
        if (!is_valid(key))
            throw InvalidAccess("Invalid field access: " + key);
    }

    void debug() const {
        std::cout << "opcode:" << opcode << " rs1:" << rs1 << " rs2:" << rs2 << " rd:" << rd << " funct3:" << funct3 << " funct7:" << funct7 << " imm:" << imm << " inst:" << inst << " type:" << t << std::endl;
    }

    bool has_op1() const {
        return (t == 'R' || t == 'I');
    }

    bool has_op2() const {
        return (t == 'R' || t == 'S');
    }
};

struct InstructionR : public InstructionBase {
    InstructionR(const Instruction &inst) : InstructionBase(inst) {
        opcode = get_digits(inst, 6, 0);
        rs1 = get_digits(inst, 11, 7);
        rs2 = get_digits(inst, 16, 12);
        rd = get_digits(inst, 20, 15);
        funct3 = get_digits(inst, 24, 20);
        funct7 = get_digits(inst, 31, 25);
        t = 'R';
    }
};

struct InstructionI : public InstructionBase {
    InstructionI(const Instruction &inst) : InstructionBase(inst) {
        opcode = get_digits(inst, 6, 0);
        rs1 = get_digits(inst, 11, 7);
        rd = get_digits(inst, 19, 15);
        funct3 = get_digits(inst, 24, 20);
        imm = expand_digit(get_digits(inst, 31, 20), 20);
        t = 'I';
    }
};

struct InstructionS : public InstructionBase {
    InstructionS(const Instruction &inst) : InstructionBase(inst) {
        opcode = get_digits(inst, 6, 0);
        rs1 = get_digits(inst, 11, 7);
        rs2 = get_digits(inst, 19, 15);
        funct3 = get_digits(inst, 24, 20);
        imm = expand_digit(get_digits(inst, 31, 25) << 5 | get_digits(inst, 11, 7), 12);
        t = 'S';
    }
};

struct InstructionB : public InstructionBase {
    InstructionB(const Instruction &inst) : InstructionBase(inst) {
        opcode = get_digits(inst, 6, 0);
        rs1 = get_digits(inst, 19, 15);
        rs2 = get_digits(inst, 24, 20);
        funct3 = get_digits(inst, 24, 20);
        imm = expand_digit((get_digits(inst, 7, 7) << 11) | (get_digits(inst, 11, 8) << 1) | (get_digits(inst, 24, 20) << 5) | (get_digits(inst, 31, 25) << 12), 13);
        t = 'B';
    }
};

struct InstructionU : public InstructionBase {
    InstructionU(const Instruction &inst) : InstructionBase(inst) {
        opcode = get_digits(inst, 6, 0);
        rd = get_digits(inst, 19, 15);
        imm = expand_digit(get_digits(inst, 31, 12) << 12, 20);
        t = 'U';
    }
};

struct InstructionJ : public InstructionBase {
    InstructionJ(const Instruction &inst) : InstructionBase(inst) {
        opcode = get_digits(inst, 6, 0);
        rd = get_digits(inst, 19, 15);
        imm = expand_digit((get_digits(inst, 20, 20) << 11) | (get_digits(inst, 30, 21) << 1) | (get_digits(inst, 20, 20) << 12) | (get_digits(inst, 31, 31) << 20), 21);
        t = 'J';
    }
};

#endif // INSTRUCTION_HPP
